#include <iostream>

template<typename T>
void print(std::ostream& os, const T& t) {
    os << t << std::endl;  // Base case: print the last argument
}

template<typename T, typename... Args>
void print(std::ostream& os, const T& t, const Args&... rest) {
    os << t << ' ';  // Print current argument followed by a space
    print(os, rest...);  // Recursively call with the remaining arguments
}

int main() {
    print(std::cout, "Hello", 42, 3.14);  // Outputs: Hello 42 3.14
    return 0;
}
